import sqlite3, duckdb, re, unicodedata
from difflib import SequenceMatcher

def norm_ws(s):
    if s is None: return ''
    return re.sub(r'\s+',' ',str(s).lower()).strip()
def deaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFKD', s) if not unicodedata.combining(c))
def simple(s):
    s=deaccent(norm_ws(s))
    s=s.replace('&',' and ')
    s=re.sub(r'[^a-z0-9]+',' ',s)
    # normalize roman volume xi to 11? minimal common
    return re.sub(r'\s+',' ',s).strip()
def charkey(s): return simple(s).replace(' ','')
def strip_year_album(s):
    s=norm_ws(s)
    s=re.sub(r'\s*\((?:19|20|unknown).*?\)\s*$','',s).strip()
    return s

