    tid,source,source_track,title,artist,album,year,length,lang=row
    t=title or ''; a=artist or ''; al=album or ''
    t_norm=norm_ws(t); a_norm=norm_ws(a); al_norm=norm_ws(al)
    tcore=t_norm; acore=a_norm; alcore=strip_year_album(al_norm)
    # strip leading track numbers/code (source 4 style)
    tcore=re.sub(r'^[0-9a-z]{2,4}\s*[- ]\s*','',tcore).strip()
    tcore=re.sub(r'^\d{3}(?=[a-z])','',tcore).strip()
    # source 2: Artist - Title
    if (not acore or source==2) and ' - ' in t_norm:
        left,right=t_norm.split(' - ',1)
        if not acore: acore=left.strip()
        tcore=right.strip()
    # source 3: Title - Album, if artist exists and album blank
    if source==3 and ' - ' in t_norm:
        left,right=t_norm.split(' - ',1)
        tcore=left.strip()
        if not alcore or alcore in ('unknown','n.a.'):
            alcore=right.strip()
    # source 1 title trailing album paren
    if tcore.endswith(')'):
        # remove last parenthetical when album resembles contents or source 1
        m=re.match(r'^(.*?)\s*\((.*)\)\s*$', tcore)
